const hex=n=>'0x'+Number(n).toString(16).toUpperCase();
export function readableStoryAction(graph,node){const values=node.args?.map((a,i)=>graph.edits.commands?.[node.at]?.args[i]??a.value)||[],v=i=>values[i],actor=n=>n===255?'Player':n===254?'This character':'Character '+n,textArg=node.args?.find(a=>a.kind==='text'),text=textArg&&(graph.edits.texts?.[textArg.value-0x08000000]?.text??graph.texts[textArg.value-0x08000000]?.text);const titles={addvar:'Increase a story value',subvar:'Decrease a story value',copyvar:'Copy a story value',setorcopyvar:'Set or copy a story value',additem:'Give an item',removeitem:'Take an item',checkitem:'Check for an item',checkitemspace:'Check Bag space',checkpcitem:'Check PC items',addpcitem:'Give an item to the PC',addmoney:'Give money',removemoney:'Take money',checkmoney:'Check money',multichoice:'Show a choice menu',multichoicedefault:'Show choices with a default',multichoicegrid:'Show a grid of choices',yesnobox:'Ask Yes or No',givemon:'Give a Pokémon',setwildbattle:'Prepare a wild battle',dowildbattle:'Start the prepared wild battle',trainerbattle:'Trainer battle',dotrainerbattle:'Start the trainer battle',warp:'Move to another map',warpsilent:'Move maps without a transition',warpdoor:'Move through a doorway',warphole:'Fall to another map',warpteleport:'Teleport to another map',setweather:'Choose weather',setobjectxyperm:'Set a character’s saved position',fadescreen:'Fade the screen',lock:'Pause this character',lockall:'Pause all characters',release:'Resume this character',releaseall:'Resume all characters',faceplayer:'Face the player',end:'Finish this event',return:'Return to the calling event',waitmessage:'Wait for dialogue',closemessage:'Close dialogue',waitbuttonpress:'Wait for a button press',waitmovement:'Wait for movement to finish',waitse:'Wait for sound',waitfanfare:'Wait for fanfare',doweather:'Apply weather',fadescreen:'Fade the screen',special:'Run an engine action',specialvar:'Run an engine action and save its result'};let title=titles[node.name]||node.name.replaceAll('_',' '),detail='',technical=false;
 if(text){title='Dialogue';detail=text.replace(/\\[nl]/g,'\n').replace(/\\p/g,'\n\n');}
 else if(node.name==='applymovement'){title='Move '+actor(v(0));detail='Open Movement to see or change each action.';}
 else if(node.name==='delay'){title='Wait';detail=v(0)+' frames (about '+(v(0)/60).toFixed(1)+' seconds).';}
 else if(['setflag','clearflag','checkflag'].includes(node.name)){title=({setflag:'Mark progress complete',clearflag:'Clear progress marker',checkflag:'Check progress marker'})[node.name];detail='Flag '+hex(v(0))+(node.name==='checkflag'?' — the following condition uses this result.':'');}
 else if(node.name==='setvar'){title='Set a story value';detail='Variable '+hex(v(0))+' = '+v(1);technical=true;}
 else if(node.name.startsWith('compare_')){title='Compare story values';detail=hex(v(0))+' compared with '+hex(v(1))+'. The following condition uses this result.';}
 else if(['goto_if','call_if'].includes(node.name)){title='Choose a branch';detail='If the previous check is '+(['less than','equal','greater than','less than or equal','greater than or equal','not equal'][v(0)]||'condition '+v(0))+', '+(node.name==='call_if'?'run a sub-event and return.':'take the matching branch.')+' Otherwise continue.';}
 else if(['goto','call'].includes(node.name)){title=node.name==='call'?'Run a sub-event':'Continue at another step';detail=node.name==='call'?'Returns here when the sub-event finishes.':'Does not return to this step.';}
 else if(['addobject','removeobject','faceplayer','turnobject','setobjectxy'].includes(node.name)){title=({addobject:'Show ',removeobject:'Hide ',turnobject:'Turn ',setobjectxy:'Position '})[node.name]?({addobject:'Show ',removeobject:'Hide ',turnobject:'Turn ',setobjectxy:'Position '})[node.name]+actor(v(0)):title;detail=node.name==='setobjectxy'?'Tile '+v(1)+', '+v(2):'';}
 else if(['playse','playbgm','playfanfare','playmoncry'].includes(node.name)){title=({playse:'Play sound',playbgm:'Play music',playfanfare:'Play fanfare',playmoncry:'Play Pokémon cry'})[node.name];detail='Native ID '+v(0);}
 else if(node.name==='setmetatile'){title='Change a map tile';detail='Tile '+v(0)+', '+v(1)+' → metatile '+hex(v(2))+'; collision argument '+v(3)+'.';}
 else if(node.adapter){title=node.adapter.name;detail=node.adapter.kind==='standard-script'?'Shared script — follow its call link to inspect it.':'Native engine routine. Only verified inputs can be edited.';}
 else if(node.external){title='Native engine action';detail='This routine is preserved. Its meaning has not been verified; open advanced details to inspect it.';}
 else if(!titles[node.name]){technical=true;detail=values.map(hex).join(', ');}
 if(node.opaque){title='Unresolved engine command';detail=node.reason;technical=false;}
 return{title,detail,technical};}
